import json,re
async def s(q,kw=None,n=4,w=600):
    r=json.loads(await web_search({"query":q}))
    print("##",q)
    for x in r[:n]:
        c=x['content']
        print(x['url'],len(c))
        if kw:
            for k in kw:
                for m in list(re.finditer(k,c))[:2]:
                    print("   >",c[max(0,m.start()-100):m.start()+w//3].replace("\n"," "))
        else: print(c[:w].replace("\n"," "))
await s("Caterpillar fourth-quarter full-year 2024 results sales and revenues profit",["Total sales and revenues","Profit \\(loss\\)","Operating profit"],3)

async def s2(q,n=3,w=1500):
    try:
        r=json.loads(await web_search({"query":q}))
